final class AutomationPackagesAcceptance {
 static void captureLimits(WorkflowSupport h)throws Exception{
  try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h)){
   var f=fixture(h,endpoint);var flowIds=new ArrayList<String>();try(var db=h.store.open()){var source=db.one("SELECT * FROM os_event_flow WHERE flow_id=?",f.get("flow"));for(int n=0;n<20;n++){String id=id();flowIds.add(id);db.update("INSERT INTO os_event_flow(flow_id,name,table_name,definition,active,revision,owner_id) VALUES(?,'Export capacity','incident',?,0,1,?)",id,JSON.writeValueAsString(source.get("definition")),source.get("owner_id"));}db.connection.commit();}
   var selection=clone(object(f.get("selection")));selection.put("flows",flowIds);selection.put("actions",List.of());var doc=capture(h,selection,200);assertEquals(20,object(doc.get("flows")).size());selection.put("actions",List.of(f.get("action")));assertEquals(400,h.json("POST",API,selection,auth("admin")).statusCode());selection.put("flows",List.of());doc=capture(h,selection,200);var bindings=clone(object(f.get("bindings")));bindings.put("groups",map());bindings.put("staff",map());var onlyActions=map("document",doc,"bindings",bindings);var input=install(onlyActions,reviewed(h,onlyActions));var receipt=object(post(h,input,200).get("receipt"));assertTrue(object(object(object(receipt.get("detail")).get("destinations")).get("flows")).isEmpty());
  }
 }
 static final String API="/api/openservice/automation-packages";
 static Map<String,Object> result(java.net.http.HttpResponse<byte[]> r,int status){return CatalogueQuestionsAcceptance.result(r,status);}
 static Map<String,Object> post(WorkflowSupport h,Object input,int status)throws Exception{return result(h.json("POST",API,input,auth("admin")),status);}
 static Map<String,Object> capture(WorkflowSupport h,Object input,int status)throws Exception{var response=h.json("POST",API,input,auth("admin"));assertEquals(status,response.statusCode(),html(response));return object(JSON.readValue(response.body(),Object.class));}
 static Map<String,Object> request(Object document,Object bindings){return map("operation","review","document",document,"bindings",bindings);}
 static Map<String,Object> reviewed(WorkflowSupport h,Map<String,Object> f)throws Exception{return object(post(h,request(f.get("document"),f.get("bindings")),200).get("review"));}
 static Map<String,Object> install(Map<String,Object> f,Map<String,Object> review){return map("operation","install","document",f.get("document"),"bindings",f.get("bindings"),"review",review.get("review"),"confirm",true);}
 static Map<String,Object> clone(Map<String,Object> input)throws Exception{return object(JSON.readValue(JSON.writeValueAsString(input),Object.class));}
 static Map<String,Object> fixture(WorkflowSupport h,ConnectorActionsAcceptance.Endpoint endpoint)throws Exception{
  h.account("PackageSourceStaff","agent");h.account("PackageDestinationStaff","agent");String source=h.add("sys_user_group").get("sys_id").toString(),destination=h.add("sys_user_group").get("sys_id").toString(),alias="package-destination";
  var config=EventWorkflowsAcceptance.config(0,"created","1",List.of(EventWorkflowsAcceptance.assign(source,"PackageSourceStaff"),EventWorkflowsAcceptance.task(source),EventWorkflowsAcceptance.note()));config.put("active",false);String flow=EventWorkflowsAcceptance.configure(h,config);var spec=ConnectorActionsAcceptance.spec(endpoint.provider.alias,0,"POST");spec.put("active",false);String action=result(h.json("POST",ConnectorActionsAcceptance.API,spec,auth("admin")),201).get("action_id").toString();
  try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Connectors.save(h.store,db,actor,map("alias",alias,"origin",endpoint.provider.origin(),"token","package-destination-token"));db.update("INSERT INTO os_group_member(group_id,user_id) VALUES(?,?)",destination,RecordAccess.owner(db,"PackageDestinationStaff"));db.connection.commit();}
  var selection=map("operation","capture","name","Reusable response <script>","version","release-1","flows",List.of(flow),"actions",List.of(action));var doc=capture(h,selection,200);var bindings=map("groups",map(source,destination),"staff",map("PackageSourceStaff","PackageDestinationStaff"),"aliases",map(endpoint.provider.alias,alias));return map("document",doc,"bindings",bindings,"selection",selection,"flow",flow,"action",action,"group",destination,"alias",alias);
 }
 static void run(WorkflowSupport h)throws Exception{
  try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h)){
   var f=fixture(h,endpoint);String exported=JSON.writeValueAsString(f.get("document"));for(String secret:List.of(endpoint.provider.origin(),"synthetic-question-token","package-destination-token","envelope","owner_id","active","revision"))assertFalse(exported.contains(secret),secret);long audits;try(var db=h.store.open()){audits=db.count("SELECT COUNT(*) FROM os_security_event");}var review=reviewed(h,f);assertEquals(0,endpoint.calls.get());assertTrue(JSON.writeValueAsString(review).contains(endpoint.provider.origin()));try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_event_flow"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_connector_action"));assertEquals(audits,db.count("SELECT COUNT(*) FROM os_security_event"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_work"));}
   var input=install(f,review);var receipt=object(post(h,input,200).get("receipt"));String id=receipt.get("package_id").toString();assertEquals(receipt,post(h,input,200).get("receipt"));var ids=object(object(receipt.get("detail")).get("destinations"));String flow=object(ids.get("flows")).get(f.get("flow")).toString(),action=object(ids.get("actions")).get(f.get("action")).toString();assertNotEquals(f.get("flow"),flow);assertNotEquals(f.get("action"),action);
   try(var db=h.store.open()){assertEquals(0,db.count("SELECT active FROM os_event_flow WHERE flow_id=?",flow));assertEquals(0,db.count("SELECT active FROM os_connector_action WHERE action_id=?",action));assertEquals(1,db.count("SELECT COUNT(*) FROM os_automation_install"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_security_event WHERE action='automation.installed'"));}
   new Store(h.environment);assertEquals(receipt,object(result(h.get(API+"/"+id,auth("admin")),200).get("receipt")));var download=h.get(API+"/"+id+"/download",auth("admin"));assertEquals(200,download.statusCode());assertEquals(f.get("document"),JSON.readValue(download.body(),Object.class));assertTrue(download.headers().firstValue("content-disposition").orElseThrow().contains("attachment"));String before=EventWorkflowsAcceptance.create(h);try(var db=h.store.open()){assertEquals(0,db.count("SELECT COUNT(*) FROM os_event_run WHERE record_id=?",before));}
   assertEquals(200,h.json("POST",EventWorkflowsAcceptance.API+"/"+flow,map("revision",1,"active",true),auth("admin")).statusCode());String record=EventWorkflowsAcceptance.create(h);EventWorkflowsAcceptance.tick(h.store);try(var db=h.store.open()){PlatformFoundationTest.bind(db);var data=object(Service.record(db,"incident",record).get("data"));assertEquals(f.get("group"),data.get("assignment_group"));assertEquals("PackageDestinationStaff",data.get("assigned_to"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_case_task WHERE parent_id=?",record));assertEquals(1,db.count("SELECT COUNT(*) FROM os_event WHERE record_id=? AND action='note'",record));}
   assertEquals(200,h.json("PUT",ConnectorActionsAcceptance.API+"/"+action,ConnectorActionsAcceptance.spec(f.get("alias").toString(),1,"POST"),auth("admin")).statusCode());String job=ConnectorActionsAcceptance.queue(h,action,ConnectorActionsAcceptance.preview(h,action,id()));assertEquals(0,endpoint.calls.get());assertTrue(new WorkWorker(h.store).runOne(System.currentTimeMillis()+1000));assertEquals("succeeded",ConnectorActionsAcceptance.job(h,job).get("state"));assertEquals(1,endpoint.calls.get());assertEquals("Bearer package-destination-token",endpoint.provider.authorization.get());
  }
 }
 static void boundaries(WorkflowSupport h)throws Exception{
  h.account("PackageReader","reader");assertEquals(401,h.get(API,null).statusCode());assertEquals(403,h.get(API,auth("PackageReader")).statusCode());assertEquals(400,h.get(API+"?x=1",auth("admin")).statusCode());assertEquals(400,h.get(API+"?x=1&x=1",auth("admin")).statusCode());assertEquals(405,h.json("PUT",API,map(),auth("admin")).statusCode());assertEquals(404,h.get(API+"/"+id(),auth("admin")).statusCode());assertEquals(405,h.json("POST",API+"/"+id(),map(),auth("admin")).statusCode());assertEquals(403,h.form("/admin/automation-packages",map(),auth("admin")).statusCode());assertEquals(400,h.protectedForm("/admin/automation-packages",map("operation","review","document","{","bindings","{}"),auth("admin")).statusCode());assertEquals(200,h.get("/admin/automation-packages",auth("admin")).statusCode());
  try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h)){
   var f=fixture(h,endpoint);for(var selection:List.of(map(),map("operation","capture","name","x","version","v","flows",List.of(),"actions",List.of()),map("operation","capture","name","x","version","v","flows",List.of(f.get("flow"),f.get("flow")),"actions",List.of()),map("operation","capture","name","x","version","v","flows",List.of("bad"),"actions",List.of()),map("operation","capture","name","x","version","v","flows","bad","actions",List.of()),map("operation","capture","name","x","version","v","flows",Collections.nCopies(21,id()),"actions",List.of()))){assertEquals(400,h.json("POST",API,selection,auth("admin")).statusCode());}
   var invalidSelection=clone(object(f.get("selection")));invalidSelection.put("flows",List.of(42));assertEquals(400,h.json("POST",API,invalidSelection,auth("admin")).statusCode());
   for(String kind:List.of("flows","actions")){var selection=clone(object(f.get("selection")));selection.put(kind,List.of(id()));assertEquals(404,h.json("POST",API,selection,auth("admin")).statusCode());}var extra=clone(object(f.get("selection")));extra.put("extra",true);assertEquals(400,h.json("POST",API,extra,auth("admin")).statusCode());for(var body:List.of(map("operation","unknown"),map("operation","review"),map("operation","review","document",f.get("document"),"bindings",f.get("bindings"),"extra",true)))assertEquals(400,h.json("POST",API,body,auth("admin")).statusCode());
   for(var changed:List.of(Map.entry("format","vendor.update-set"),Map.entry("package_id","bad"),Map.entry("source_schema",0),Map.entry("source_schema",Migrations.VERSION+1),Map.entry("source_schema","94"),Map.entry("flows",List.of()),Map.entry("name","x".repeat(262145)),Map.entry("actions",map("bad",map())))){var doc=clone(object(f.get("document")));doc.put(changed.getKey(),changed.getValue());assertEquals(400,h.json("POST",API,request(doc,f.get("bindings")),auth("admin")).statusCode());}var doc=clone(object(f.get("document")));doc.put("extra",1);assertEquals(400,h.json("POST",API,request(doc,f.get("bindings")),auth("admin")).statusCode());doc=clone(object(f.get("document")));doc.put("flows",map());doc.put("actions",map());assertEquals(400,h.json("POST",API,request(doc,f.get("bindings")),auth("admin")).statusCode());doc=clone(object(f.get("document")));object(doc.get("flows")).put(f.get("flow").toString(),"scalar");assertEquals(400,h.json("POST",API,request(doc,f.get("bindings")),auth("admin")).statusCode());
   var input=install(f,reviewed(h,f));input.put("confirm",false);assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode());input.put("confirm",true);input.put("review","stale");assertEquals(409,h.json("POST",API,input,auth("admin")).statusCode());
   var form=map("operation","review","document",JSON.writeValueAsString(f.get("document")),"bindings",JSON.writeValueAsString(f.get("bindings")));assertEquals(200,h.protectedForm("/admin/automation-packages",form,auth("admin")).statusCode());form.put("operation","install");form.put("review",reviewed(h,f).get("review"));form.put("confirm","false");assertEquals(400,h.protectedForm("/admin/automation-packages",form,auth("admin")).statusCode());form.put("confirm","true");assertEquals(200,h.protectedForm("/admin/automation-packages",form,auth("admin")).statusCode());assertEquals(403,h.get(API+"/"+object(f.get("document")).get("package_id")+"/download",auth("PackageReader")).statusCode());
  }
 }
 static void bindingsAndValidation(WorkflowSupport h)throws Exception{
  try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h)){
   var f=fixture(h,endpoint);for(var bindings:List.of(map(),map("groups",map(),"staff",map(),"aliases",map()),map("groups",map(),"staff",map(),"aliases",map(),"extra",map())))assertEquals(400,h.json("POST",API,request(f.get("document"),bindings),auth("admin")).statusCode());for(String kind:List.of("groups","staff","aliases")){var bindings=clone(object(f.get("bindings")));var values=object(bindings.get(kind));String key=values.keySet().iterator().next();values.put(key,"");assertEquals(400,h.json("POST",API,request(f.get("document"),bindings),auth("admin")).statusCode());values.put(key,kind.equals("groups")?id():"missing");assertEquals(kind.equals("staff")?400:404,h.json("POST",API,request(f.get("document"),bindings),auth("admin")).statusCode());}
   for(Object actions:List.of("scalar",List.of("scalar"),List.of(map("kind","assign","group_id",id(),"assignee",1)))){var doc=clone(object(f.get("document")));object(object(doc.get("flows")).get(f.get("flow"))).put("actions",actions);assertEquals(400,h.json("POST",API,request(doc,f.get("bindings")),auth("admin")).statusCode());}
   var doc=clone(object(f.get("document")));var action=object(object(doc.get("actions")).get(f.get("action")));action.put("active",true);assertEquals(400,h.json("POST",API,request(doc,f.get("bindings")),auth("admin")).statusCode());doc=clone(object(f.get("document")));object(object(doc.get("actions")).get(f.get("action"))).put("method","GET");long audits;try(var db=h.store.open()){audits=db.count("SELECT COUNT(*) FROM os_security_event");}assertEquals(400,h.json("POST",API,request(doc,f.get("bindings")),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_event_flow"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_connector_action"));assertEquals(audits,db.count("SELECT COUNT(*) FROM os_security_event"));}
   doc=clone(object(f.get("document")));doc.put("actions",map());var definition=object(object(doc.get("flows")).get(f.get("flow")));definition.put("actions",List.of(EventWorkflowsAcceptance.note()));var empty=map("groups",map(),"staff",map(),"aliases",map());assertEquals(200,h.json("POST",API,request(doc,empty),auth("admin")).statusCode());definition.put("actions",List.of(EventWorkflowsAcceptance.assign(object(object(f.get("bindings")).get("groups")).keySet().iterator().next(),"")));var noStaff=clone(object(f.get("bindings")));noStaff.put("staff",map());noStaff.put("aliases",map());assertEquals(200,h.json("POST",API,request(doc,noStaff),auth("admin")).statusCode());
   var large=clone(object(f.get("document")));object(large.get("flows")).clear();for(int n=0;n<21;n++)object(large.get("flows")).put(id(),definition);assertEquals(400,h.json("POST",API,request(large,noStaff),auth("admin")).statusCode());
  }
 }
 static void changes(WorkflowSupport h)throws Exception{
  try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h)){
   var f=fixture(h,endpoint);var review=reviewed(h,f);try(var db=h.store.open()){db.update("UPDATE os_user SET auth_revision=auth_revision+1 WHERE name='admin'");db.connection.commit();}assertEquals(409,h.json("POST",API,install(f,review),auth("admin")).statusCode());review=reviewed(h,f);try(var db=h.store.open()){String actor=PlatformFoundationTest.bind(db);Connectors.save(h.store,db,actor,map("alias",f.get("alias"),"origin",endpoint.provider.origin(),"token","rotated-package-token"));db.connection.commit();}assertEquals(409,h.json("POST",API,install(f,review),auth("admin")).statusCode());Object allowed=endpoint.provider.settings.put("CONNECTOR_ALLOWED_ORIGINS","");assertEquals(400,h.json("POST",API,request(f.get("document"),f.get("bindings")),auth("admin")).statusCode());endpoint.provider.settings.put("CONNECTOR_ALLOWED_ORIGINS",allowed);
   Map<String,Object> original;try(var db=h.store.open()){original=Service.schema(db,"incident");}review=reviewed(h,f);var schema=new LinkedHashMap<>(original);schema.put("label","Changed destination schema");ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(409,h.json("POST",API,install(f,review),auth("admin")).statusCode());schema.put("record_roles",map("read",List.of("agent")));ReferencePickerAcceptance.writeSchema(h,"incident",schema);assertEquals(403,h.json("POST",API,f.get("selection"),auth("admin")).statusCode());ReferencePickerAcceptance.writeSchema(h,"incident",original);
   review=reviewed(h,f);try(var db=h.store.open()){PlatformFoundationTest.bind(db);Service.update(db,"sys_user_group",Service.record(db,"sys_user_group",f.get("group").toString()),map("short_description","Changed destination team"),"admin","admin",null);db.connection.commit();}assertEquals(409,h.json("POST",API,install(f,review),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET active=0 WHERE name='PackageDestinationStaff'");db.connection.commit();}assertEquals(400,h.json("POST",API,request(f.get("document"),f.get("bindings")),auth("admin")).statusCode());try(var db=h.store.open()){db.update("UPDATE os_user SET active=1 WHERE name='PackageDestinationStaff'");db.connection.commit();}
   var input=install(f,reviewed(h,f));try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var a=pool.submit(()->post(h,input,200));var b=pool.submit(()->post(h,input,200));assertEquals(a.get().get("receipt"),b.get().get("receipt"));}try(var db=h.store.open()){assertEquals(2,db.count("SELECT COUNT(*) FROM os_event_flow"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_connector_action"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_automation_install"));}
   for(String change:List.of("document","bindings","review")){var changed=clone(input);if(change.equals("document"))object(changed.get("document")).put("name","Different package");else if(change.equals("bindings"))object(object(changed.get("bindings")).get("staff")).put("PackageSourceStaff","PackageSourceStaff");else changed.put("review","another review");assertEquals(409,h.json("POST",API,changed,auth("admin")).statusCode());}
  }
 }
 static void limitsAndRollback(WorkflowSupport h)throws Exception{
  try(var endpoint=new ConnectorActionsAcceptance.Endpoint(h)){
   var f=fixture(h,endpoint);try(var db=h.store.open()){var row=db.one("SELECT * FROM os_event_flow WHERE flow_id=?",f.get("flow"));for(int n=1;n<100;n++)db.update("INSERT INTO os_event_flow(flow_id,name,table_name,definition,active,revision,owner_id) VALUES(?,'Capacity','incident',?,0,1,?)",id(),JSON.writeValueAsString(row.get("definition")),row.get("owner_id"));db.connection.commit();}assertEquals(400,h.json("POST",API,request(f.get("document"),f.get("bindings")),auth("admin")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_event_flow WHERE name='Capacity'");for(int n=1;n<200;n++)db.update("INSERT INTO os_connector_action(action_id,name,alias,method,path,inputs,active,revision) VALUES(?,'Capacity',?,'POST','/write','[]',0,1)",id(),f.get("alias"));db.connection.commit();}assertEquals(400,h.json("POST",API,request(f.get("document"),f.get("bindings")),auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_event_flow"));db.update("DELETE FROM os_connector_action WHERE name='Capacity'");for(int n=0;n<1000;n++)db.update("INSERT INTO os_automation_install(package_id,name,version,fingerprint,actor_id,created,detail) VALUES(?,'Capacity','v','hash','actor',?,'{}')",id(),now());db.connection.commit();}var input=install(f,reviewed(h,f));assertEquals(400,h.json("POST",API,input,auth("admin")).statusCode());try(var db=h.store.open()){db.update("DELETE FROM os_automation_install");db.update("CREATE UNIQUE INDEX fixture_package_receipt_failure ON os_security_event(action) WHERE action='automation.installed'");PlatformFoundationTest.bind(db);SecurityEvents.record(db,db.viewerId,db.viewerId,"automation.installed",map("fixture",true));db.connection.commit();}assertEquals(500,h.json("POST",API,input,auth("admin")).statusCode());try(var db=h.store.open()){assertEquals(1,db.count("SELECT COUNT(*) FROM os_event_flow"));assertEquals(1,db.count("SELECT COUNT(*) FROM os_connector_action"));assertEquals(0,db.count("SELECT COUNT(*) FROM os_automation_install"));db.update("DROP INDEX fixture_package_receipt_failure");db.connection.commit();}post(h,input,200);
  }
 }
}
